INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',590,'{"_type":"chat:Message","id":"-5124234082:2921","threadId":"telegram:-5124234082","text":"Hi Pepa,\nWe’re going to be 9 days in Annecy with the 3 kids. We will stay in the apartment next door of my brother’s one. We will arrive in Annecy on August 10 around 4pm and leave on August 9 around 12pm. \nWe want to make an online order on a local supermarket to be delivered on Aug 10 end of the day so that we don’t have to do groceries for the whole week. \nI want you to brainstorm on what our week will look like, think of the best way to handle the kid’s food and ours, make a list of groceries to prepare the order, and finally compare what are the best supermarket options for ordering online in Annecy.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Hi Pepa,\nWe’re going to be 9 days in Annecy with the 3 kids. We will stay in the apartment next door of my brother’s one. We will arrive in Annecy on August 10 around 4pm and leave on August 9 around 12pm.\nWe want to make an online order on a local supermarket to be delivered on Aug 10 end of the day so that we don’t have to do groceries for the whole week.\nI want you to brainstorm on what our week will look like, think of the best way to handle the kid’s food and ours, make a list of groceries to prepare the order, and finally compare what are the best supermarket options for ordering online in Annecy.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":251,"offset":612}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":251,"offset":612}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":251,"offset":612}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-05T17:05:39.000Z","edited":false},"attachments":[],"isMention":false}',1786554339893);
