INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',475,'{"_type":"chat:Message","id":"8641420749:1138","threadId":"telegram:8641420749","text":"Donne moi le plan pour les 10 jours à Annecy, version courte, que je vais enviyer a mon frere pour qu’il ait une idee.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Donne moi le plan pour les 10 jours à Annecy, version courte, que je vais enviyer a mon frere pour qu’il ait une idee.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":119,"offset":118}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":119,"offset":118}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":119,"offset":118}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-07T09:24:39.000Z","edited":false},"attachments":[],"isMention":false}',1786699478779);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',476,'{"_type":"chat:Message","id":"8641420749:1143","threadId":"telegram:8641420749","text":"/done j’ai décidé de faire 1h30 aujourd’hui, je pourrai faire plus long demain. la HR était plus élevée que d’habitude sur la premiere moitié du ride. Je pense que c’est pcq j’ai bu un grand café 2h avant le ride et pcq j’ai dormi 5h la nuit derniere. Mais pas sensation d’être fatigué sur le velo. Les jambes etaient biens. Par contre 1/10 au genou droit tout du long, mais pas douleur de genou habituelle, douleur du choc d’hier.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"/done j’ai décidé de faire 1h30 aujourd’hui, je pourrai faire plus long demain. la HR était plus élevée que d’habitude sur la premiere moitié du ride. Je pense que c’est pcq j’ai bu un grand café 2h avant le ride et pcq j’ai dormi 5h la nuit derniere. Mais pas sensation d’être fatigué sur le velo. Les jambes etaient biens. Par contre 1/10 au genou droit tout du long, mais pas douleur de genou habituelle, douleur du choc d’hier.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":432,"offset":431}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":432,"offset":431}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":432,"offset":431}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-07T11:11:20.000Z","edited":false},"attachments":[],"isMention":false}',1786705880253);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',477,'{"_type":"chat:Message","id":"8641420749:1147","threadId":"telegram:8641420749","text":"I need to give you some more context about the weeks that are coming. So, on Sunday 9th we are traveling back to Lisbon by car so I will not be able to train. On Monday 10th we are flying to Annecy and traveling then from Geneva to Annecy so I will probably not be able to train as well. on both days maybe I could do  Reno and then from 11 to 15 we will be alone with the kids and my brother so probably the training will have to be relatively short like one two hours but then from 15 to 18 included so the 15 16 17 18 my parents will be there so they can take care of the kids and then I will be able to cycle longer hours in the end I will have a bike especially on those 15 to 18 days and after that on the 19th we are traveling back to Lisbon so no training and on the 20s we are traveling to the north of portugal so probably also no training adapt the plan accordingly","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"I need to give you some more context about the weeks that are coming. So, on Sunday 9th we are traveling back to Lisbon by car so I will not be able to train. On Monday 10th we are flying to Annecy and traveling then from Geneva to Annecy so I will probably not be able to train as well. on both days maybe I could do  Reno and then from 11 to 15 we will be alone with the kids and my brother so probably the training will have to be relatively short like one two hours but then from 15 to 18 included so the 15 16 17 18 my parents will be there so they can take care of the kids and then I will be able to cycle longer hours in the end I will have a bike especially on those 15 to 18 days and after that on the 19th we are traveling back to Lisbon so no training and on the 20s we are traveling to the north of portugal so probably also no training adapt the plan accordingly","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":877,"offset":876}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":877,"offset":876}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":877,"offset":876}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-07T11:35:47.000Z","edited":false},"attachments":[],"isMention":false}',1786707346966);
