INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',503,'{"_type":"chat:Message","id":"8641420749:214","threadId":"telegram:8641420749","text":"Lance la passe répertoire. Lis le SKILL.md wiki : récupère aussi les participants des événements d''agenda, ils n''ont jamais été lus.\nUne fois que c’est fait je veux que tu rajoutes une année d’historique en passe repertoire, email, calendar. \nMonitor la limite de session token, lorsque tu t’en approches, tu créés une task qui te dira de reprendra la passe une fois la session renouvelée au bon schedule. Et ainsi de suite jusqu’à couvrir toutes les années d’email et de calendar.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Lance la passe répertoire. Lis le SKILL.md wiki : récupère aussi les participants des événements d''agenda, ils n''ont jamais été lus.\nUne fois que c’est fait je veux que tu rajoutes une année d’historique en passe repertoire, email, calendar.\nMonitor la limite de session token, lorsque tu t’en approches, tu créés une task qui te dira de reprendra la passe une fois la session renouvelée au bon schedule. Et ainsi de suite jusqu’à couvrir toutes les années d’email et de calendar.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":239,"offset":481}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":239,"offset":481}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":239,"offset":481}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-08T22:19:23.000Z","edited":false},"attachments":[],"isMention":false}',1786832363226);
